import{_ as d,a0 as a,w as p,s as w,ao as l,I as e,x as n,a1 as u,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"Qshutdown – 一个先进的关机神器 | LCTT x X-CMD","titleTemplate":false,"description":"Qshutdown – 一个先进的关机神器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Qshutdown – 一个先进的关机神器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Qshutdown – 一个先进的关机神器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141119 Qshutdown--An avanced shutdown tool","title":"Qshutdown – 一个先进的关机神器","tag":"201412","desc":""},"relativePath":"201412/20141119 Qshutdown--An avanced shutdown tool.md","filePath":"[post].md"}'),r={name:"201412/20141119 Qshutdown--An avanced shutdown tool.md"};function h(i,t,m,f,g,T){const o=a("Link");return p(),w("div",null,[t[13]||(t[13]=l(`<h1 id="qshutdown-–-一个先进的关机神器" tabindex="-1">Qshutdown – 一个先进的关机神器 <a class="header-anchor" href="#qshutdown-–-一个先进的关机神器" aria-label="Permalink to “Qshutdown – 一个先进的关机神器”">​</a></h1><p>qshutdown是一个QT程序，用于让计算机在指定时间或者在几分钟后关机/重启/挂起/睡眠。对于那些只在特定时间使用计算机工作的人而言，可能很有用。</p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/12.png" alt=""></p><p>qshutdown将在最后70秒时显示3次警告提醒。（如果设置了1分钟或者“本地时间+1”，它只会显示一次。）</p><p>该程序使用qdbus来发送关机/重启/挂起/睡眠请求到gnome或kde会话管理器，或者到HAL或DeviceKit，而如果这些都没有工作，那么就会使用‘sudo shutdown -P now’命令进行关机（注意，当发送请求到HAL或DeviceKit，或者使用shutdown命令时，会话不会被保存。如果使用shutdown命令，该程序只会被关机或重启）。所以，如果在shutdown或reboot时间到时却什么都没发生，这就意味着用户缺少使用shutdown命令的权限。</p><p>在这种情况下，你可以进行以下操作：</p><p>粘贴以下信息到终端：“EDITOR:nano sudo -E visudo”并添加此行：“* ALL = NOPASSWD:/sbin/shutdown”这里*替换为你的“用户名”或“%组名”。</p><p>倒计时最大计数为1440分钟（24小时）。配置文件（和日志文件）位于~/.qshutdown，配置文件为：qshutdown.conf。</p><p>对于管理员：</p><p>在将qshutdonw.conf中的Lock_all选项设置为true后，用户将不能修改设置。如果你使用“sudo chown root -R ~/.qshutdown”和“sudo chmod 744 ~/.qshutdown/qshutdown.conf”命令修改qshutdown.conf的权限后，用户将不能修改配置文件。</p><h3 id="ubuntu中安装qshutdown" tabindex="-1">Ubuntu中安装Qshutdown <a class="header-anchor" href="#ubuntu中安装qshutdown" aria-label="Permalink to “Ubuntu中安装Qshutdown”">​</a></h3><p>打开终端，然后运行以下命令</p><pre><code>sudo apt-get install qshutdown
</code></pre><h3 id="屏幕截图" tabindex="-1">屏幕截图 <a class="header-anchor" href="#屏幕截图" aria-label="Permalink to “屏幕截图”">​</a></h3><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/23.png" alt=""></p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/31.png" alt=""></p><p><img src="http://www.ubuntugeek.com/wp-content/uploads/2014/11/41.png" alt=""></p><hr>`,18)),e("p",null,[t[1]||(t[1]=n("via: ",-1)),u(o,{href:"http://www.ubuntugeek.com/qshutdown-an-avanced-shutdown-tool.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://www.ubuntugeek.com/qshutdown-an-avanced-shutdown-tool.html",-1)])]),_:1})]),e("p",null,[t[5]||(t[5]=n("作者：",-1)),u(o,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:s(()=>[...t[2]||(t[2]=[n("ruchi",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),u(o,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),u(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("本文由 ",-1)),u(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),u(o,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const L=d(r,[["render",h]]);export{q as __pageData,L as default};
